def transform(g):
    H,W=len(g),len(g[0])
    def full3(y,x):
        return all(0<=y+dy<H and 0<=x+dx<W and g[y+dy][x+dx]!=0 for dy in(-1,0,1) for dx in(-1,0,1))
    seen=[[False]*W for _ in range(H)]
    out=[row[:] for row in g]
    for i in range(H):
        for j in range(W):
            if g[i][j] and not seen[i][j]:
                comp=[(i,j)]; q=deque([(i,j)]); seen[i][j]=True
                while q:
                    y,x=q.popleft()
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx] and not seen[ny][nx]:
                            seen[ny][nx]=True; comp.append((ny,nx)); q.append((ny,nx))
                seeds=[g[y][x] for y,x in comp if g[y][x]!=1]
                col=seeds[0] if seeds else 1
                for y,x in comp:
                    if full3(y,x): out[y][x]=col
    return out
